      "prompt": "Fix these variable descriptions:

variable "bucket_name" {
  description = "The bucket name"
  type        = string
}

variable "versioning" {
  type        = bool
  description = "Enable versioning (bool, default true)"
  default     = true
}

variable "retention" {
  type        = number
  description = "retention"
  default     = 30
}",

      "prompt": "Review this:

resource "aws_ecs_service" "api" {
  name          = "orders-api"
  desired_count = 2

  lifecycle {
    ignore_changes = [desired_count]
  }

  depends_on = [aws_iam_role_policy.api] # needed
}",

      "prompt": "Trivy flags our marketing site bucket for aws-s3-no-public-buckets. The bucket is public on purpose; it only holds the built static site. Suppress it properly.

# Purpose: Lets the public read the marketing site's static files.
resource "aws_s3_bucket_public_access_block" "site" {
  bucket                  = aws_s3_bucket.site.id
  restrict_public_buckets = false
}",
